public static Node<Integer> evens(Node<Integer> first) {
    Node<Integer> head = null;
    Node<Integer> last = null;
    Node<Integer> p = first;
    while (p != null) {
        if (p.getValue() % 2 == 0) {
            Node<Integer> node = new Node<Integer>(p.getValue());
            if (head == null) {
                head = node;
            } else {
                last.setNext(node);
            }
            last = node;
        }
        p = p.getNext();
    }
    return head;
}

public static Node<Integer> removeAll(Node<Integer> first, int x) {
    while (first != null && first.getValue() == x) {
        first = first.getNext();
    }
    if (first == null) {
        return null;
    }
    Node<Integer> p = first;
    while (p.getNext() != null) {
        if (p.getNext().getValue() == x) {
            p.setNext(p.getNext().getNext());
        } else {
            p = p.getNext();
        }
    }
    return first;
}

